-- App passwords: for apps that cannot sign in with a passkey (WebDAV, later
-- CalDAV and mail). Generated by the server with 130 bits of randomness, so a
-- SHA-256 hash is enough to store them (like session tokens); argon2 would be
-- needed for passwords people choose, and would be far too slow here, since
-- protocol clients send the password with every request.

-- +goose Up
CREATE TABLE identity.app_passwords (
    id           uuid        PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES identity.users (id) ON DELETE CASCADE,
    name         text        NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    token_hash   bytea       NOT NULL UNIQUE,
    created_at   timestamptz NOT NULL,
    last_used_at timestamptz
);
CREATE INDEX app_passwords_user_idx ON identity.app_passwords (user_id);

-- +goose Down
DROP TABLE identity.app_passwords;
